<?php declare(strict_types=1); session_start(); if(empty($_SESSION['user'])||($_SESSION['user']['rol']??'')!=='superadmin'){http_response_code(403);exit('Acceso no autorizado.');}$config=require __DIR__.'/config.php';function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$stats=[];$stats['tiendas']=$pdo->query("SELECT COUNT(*) FROM tiendas WHERE estado='activa'")->fetchColumn();$stats['productos']=$pdo->query("SELECT COUNT(*) FROM productos WHERE estado='activo'")->fetchColumn();$stats['pedidos']=$pdo->query("SELECT COUNT(*) FROM pedidos WHERE estado_pago='pendiente_validacion'")->fetchColumn();$stats['usuarios']=$pdo->query('SELECT COUNT(*) FROM usuarios')->fetchColumn();$recent=$pdo->query('SELECT codigo_pedido,cliente_nombre,monto_total,estado_pago,estado_envio FROM pedidos ORDER BY id DESC LIMIT 8')->fetchAll();}catch(Throwable $e){http_response_code(500);exit('No se pudo cargar el dashboard.');}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard</title><style>body{font-family:system-ui;background:#f6f3ee;margin:0;color:#171717}main{max-width:1000px;margin:auto;padding:30px 20px}a{color:#886c42}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}.card{background:#fff;padding:20px;border-radius:16px;margin:14px 0}.metric{font-size:2.2rem;font-weight:700}.links{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px}.links a{display:block;padding:14px;border:1px solid #eadfce;border-radius:10px;text-decoration:none}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px 7px;border-bottom:1px solid #eee}th{color:#666;font-size:13px}</style></head><body><main><p><a href="panel.php">← Panel</a> · <a href="logout.php">Cerrar sesión</a></p><h1>Dashboard administrativo</h1><section class="cards"><div class="card"><div>Tiendas activas</div><div class="metric"><?=h((string)$stats['tiendas'])?></div></div><div class="card"><div>Productos publicados</div><div class="metric"><?=h((string)$stats['productos'])?></div></div><div class="card"><div>Pagos por validar</div><div class="metric"><?=h((string)$stats['pedidos'])?></div></div><div class="card"><div>Usuarios</div><div class="metric"><?=h((string)$stats['usuarios'])?></div></div></section><section class="card"><h2>Accesos rápidos</h2><div class="links"><a href="tiendas-admin.php">Administrar tiendas →</a><a href="productos-admin.php">Administrar productos →</a><a href="categorias-admin.php">Administrar categorías →</a><a href="pedidos-admin.php">Gestionar pedidos →</a><a href="usuarios-admin.php">Usuarios y permisos →</a></div></section><section class="card"><h2>Pedidos recientes</h2><table><thead><tr><th>Código</th><th>Cliente</th><th>Total</th><th>Pago</th><th>Envío</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><a href="pedido.php?code=<?=urlencode($r['codigo_pedido'])?>"><?=h($r['codigo_pedido'])?></a></td><td><?=h($r['cliente_nombre'])?></td><td>S/ <?=h((string)$r['monto_total'])?></td><td><?=h($r['estado_pago'])?></td><td><?=h($r['estado_envio'])?></td></tr><?php endforeach;if(!$recent):?><tr><td colspan="5">No hay pedidos.</td></tr><?php endif;?></tbody></table></section></main></body></html>
